	}
	if v, ok := l.cache[key]; ok {
		return v, nil
	}
	v, err := l.src(key)
	if err != nil {
		return "", err
	}
	if l.cache == nil {
		l.cache = make(map[string]string)
	}
	l.cache[key] = v
	return v, nil
