			v = v + r
		} else {
			v = v - r
		}
	}
}

func (p *parser) parseTerm() (float64, error) {
	p.skipSpace()
	v, err := p.parseFactor()
	if err != nil {
		return 0, err
	}
	for {
		p.skipSpace()
		op := p.peek()
		if op != '*' && op != '/' {
			return v, nil
		}
		p.pos++
		p.skipSpace()
		r, err := p.parseFactor()
		if err != nil {
			return 0, err
		}
		if op == '*' {
			v = v * r
		} else {
			if r == 0 {
				return 0, fmt.Errorf("division by zero")
			}
			v = v / r
		}
	}
}

func (p *parser) parseFactor() (float64, error) {
	p.skipSpace()
	if p.peek() == '-' {
		p.pos++
		p.skipSpace()
		v, err := p.parseFactor()
		if err != nil {
			return 0, err
		}
		return -v, nil
	}
	if p.peek() == '+' {
		p.pos++
		return p.parseFactor()
	}
	v, err := p.parseBase()
	if err != nil {
		return 0, err
	}
	p.skipSpace()
	if p.peek() == '^' {
		p.pos++
		p.skipSpace()
		r, err := p.parseFactor()
		if err != nil {
			return 0, err
		}
		v = math.Pow(v, r)
	}
